const state={token:null,expiresAt:0,currentPath:"",listPage:1,searchPage:1,totalList:0,totalSearch:0}
const apiBase="/api/v1"
function setStatus(t){const el=document.getElementById("status");el.textContent=t}
function showAuth(){document.getElementById("authPanel").classList.remove("hidden");document.getElementById("appPanel").classList.add("hidden");setStatus("未登录")}
function showApp(){document.getElementById("authPanel").classList.add("hidden");document.getElementById("appPanel").classList.remove("hidden");setStatus("已登录")}
function saveToken(tok,ttl){state.token=tok;state.expiresAt=Date.now()+ttl*1000;localStorage.setItem("lms_token",tok);localStorage.setItem("lms_token_exp",String(state.expiresAt))}
function loadToken(){const tok=localStorage.getItem("lms_token");const exp=Number(localStorage.getItem("lms_token_exp")||"0");if(tok&&exp>Date.now()){state.token=tok;state.expiresAt=exp;return true}return false}
async function apiFetch(path,opt){const o=opt||{};o.headers=o.headers||{};if(!o.headers["Content-Type"]&&o.method&&o.method!=="GET")o.headers["Content-Type"]="application/json";if(state.token)o.headers["Authorization"]="Bearer "+state.token;const res=await fetch(apiBase+path,o);return res}
async function getCode(){const name=document.getElementById("deviceName").value.trim();const res=await apiFetch("/auth/device/code",{method:"POST",body:JSON.stringify({device_name:name})});if(!res.ok){alert("获取认证码失败");return}const data=await res.json();if(data.disabled){alert("服务端未启用设备认证");return}document.getElementById("deviceCode").value=data.code;document.getElementById("codeTTL").textContent="有效期 "+data.expires_in+" 秒"}
async function verify(){const code=document.getElementById("deviceCode").value.trim();const res=await apiFetch("/auth/device/verify",{method:"POST",body:JSON.stringify({code})});if(!res.ok){alert("认证失败");return}const data=await res.json();if(data.disabled){alert("服务端未启用设备认证");return}saveToken(data.token,data.expires_in);showApp();reloadList()}
async function reloadList(){const q=new URLSearchParams();const f=document.getElementById("filterInput").value.trim();const s=document.getElementById("listSort").value;const o=document.getElementById("listOrder").value;q.set("page",String(state.listPage));q.set("page_size","50");if(f)q.set("filter",f);if(s)q.set("sort",s);if(o)q.set("order",o);const path=state.currentPath;const url=path?("/browse?"+q.toString()+"&path="+encodeURIComponent(path)):("/browse?"+q.toString());const res=await apiFetch(url,{method:"GET"});if(!res.ok){if(res.status===401){showAuth();return}alert("加载目录失败");return}const data=await res.json();state.totalList=data.total||0;state.currentPath=data.current||"";renderCurrentLabel();renderList(Array.isArray(data.items)?data.items:[]);updateListPager()}
function getParentPath(p){if(!p)return"";const i=Math.max(p.lastIndexOf("/"),p.lastIndexOf("\\"));if(i>0){return p.slice(0,i)}return""}
function renderCurrentLabel(){const el=document.getElementById("currentLabel");el.textContent=state.currentPath?("当前位置："+state.currentPath):"顶层目录"}
function renderList(items){const body=document.getElementById("itemsBody");body.innerHTML="";(Array.isArray(items)?items:[]).forEach(it=>{const tr=document.createElement("tr");const name=document.createElement("td");name.textContent=it.name;const type=document.createElement("td");type.textContent=it.type;type.className=it.type==="dir"?"type-dir":"type-file";const size=document.createElement("td");size.textContent=String(it.size);size.className="size";const mtime=document.createElement("td");mtime.textContent=new Date(it.mod_time).toLocaleString();const ops=document.createElement("td");const det=document.createElement("button");det.textContent="详情";det.onclick=()=>showDetails(it.path);ops.appendChild(det);if(it.type==="dir"){const open=document.createElement("button");open.textContent="打开";open.onclick=()=>{state.currentPath=it.path;state.listPage=1;reloadList()};ops.appendChild(open)}else{const btn=document.createElement("button");btn.textContent="下载";btn.onclick=()=>download(it.path,it.name);ops.appendChild(btn)}tr.appendChild(name);tr.appendChild(type);tr.appendChild(size);tr.appendChild(mtime);tr.appendChild(ops);body.appendChild(tr)})}
async function runSearch(){const q=new URLSearchParams();const query=document.getElementById("searchInput").value.trim();const tp=document.getElementById("searchType").value;const sort=document.getElementById("searchSort").value;const order=document.getElementById("searchOrder").value;q.set("page",String(state.searchPage));q.set("page_size","50");if(query)q.set("q",query);if(tp)q.set("type",tp);if(sort)q.set("sort",sort);if(order)q.set("order",order);const res=await apiFetch("/search?"+q.toString(),{method:"GET"});if(!res.ok){if(res.status===401){showAuth();return}alert("搜索失败");return}const data=await res.json();state.totalSearch=data.total||0;renderSearch(Array.isArray(data.items)?data.items:[]);updateSearchPager()}
function renderSearch(items){const body=document.getElementById("searchBody");body.innerHTML="";(Array.isArray(items)?items:[]).forEach(it=>{const tr=document.createElement("tr");const name=document.createElement("td");name.textContent=it.name;const type=document.createElement("td");type.textContent=it.type;type.className=it.type==="dir"?"type-dir":"type-file";const size=document.createElement("td");size.textContent=String(it.size);size.className="size";const mtime=document.createElement("td");mtime.textContent=new Date(it.mod_time).toLocaleString();const parent=document.createElement("td");parent.textContent=it.parent||"";const ops=document.createElement("td");const det=document.createElement("button");det.textContent="详情";det.onclick=()=>showDetails(it.path);ops.appendChild(det);if(it.type==="file"){const btn=document.createElement("button");btn.textContent="下载";btn.onclick=()=>download(it.path,it.name);ops.appendChild(btn)}tr.appendChild(name);tr.appendChild(type);tr.appendChild(size);tr.appendChild(mtime);tr.appendChild(parent);tr.appendChild(ops);body.appendChild(tr)})}
async function download(path,name){const q=new URLSearchParams();q.set("path",encodeURIComponent(path));const res=await apiFetch("/download?"+q.toString(),{method:"GET"});if(!res.ok){alert("下载失败");return}const blob=await res.blob();const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=name||"下载文件";document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}
async function showDetails(path){const q=new URLSearchParams();q.set("path",encodeURIComponent(path));const res=await apiFetch("/meta?"+q.toString(),{method:"GET"});if(!res.ok){alert("获取详情失败");return}const it=await res.json();alert("名称: "+(it.name||"")+"\n类型: "+(it.type||"")+"\n大小: "+(it.size||0)+"\n修改时间: "+(new Date(it.mod_time)).toLocaleString()+"\n路径: "+(it.path||""))}
function logout(){localStorage.removeItem("lms_token");localStorage.removeItem("lms_token_exp");state.token=null;state.expiresAt=0;showAuth()}
function updateListPager(){document.getElementById("listPageLabel").textContent="第 "+state.listPage+" 页，共 "+Math.ceil(state.totalList/50)+" 页"}
function updateSearchPager(){document.getElementById("searchPageLabel").textContent="第 "+state.searchPage+" 页，共 "+Math.ceil(state.totalSearch/50)+" 页"}
function bindEvents(){document.getElementById("btnGetCode").onclick=getCode;document.getElementById("btnVerify").onclick=verify;document.getElementById("btnLogout").onclick=logout;document.getElementById("btnReload").onclick=reloadList;document.getElementById("btnSearch").onclick=()=>{state.searchPage=1;runSearch()};document.getElementById("btnPrevList").onclick=()=>{if(state.listPage>1){state.listPage--;reloadList()}};document.getElementById("btnNextList").onclick=()=>{const max=Math.max(1,Math.ceil(state.totalList/50));if(state.listPage<max){state.listPage++;reloadList()}};document.getElementById("btnPrevSearch").onclick=()=>{if(state.searchPage>1){state.searchPage--;runSearch()}};document.getElementById("btnNextSearch").onclick=()=>{const max=Math.max(1,Math.ceil(state.totalSearch/50));if(state.searchPage<max){state.searchPage++;runSearch()}};document.getElementById("btnUp").onclick=()=>{if(state.currentPath){state.currentPath=getParentPath(state.currentPath);state.listPage=1;reloadList()}}}
function init(){bindEvents();if(loadToken()){showApp();reloadList()}else{showAuth()}}
document.addEventListener("DOMContentLoaded",init)

